def sha(value):return hashlib.sha256(value).hexdigest()
def encode(value):return json.dumps(value,sort_keys=True,separators=(',',':')).encode()
def require(value,code):
 if not value:raise RuntimeError(code)

def review():
 require(os.geteuid()==0,'root_public_stager_required')
 for path in [*OPS.parents,OPS]:
  info=path.lstat();require(stat.S_ISDIR(info.st_mode)and info.st_uid==info.st_gid==0 and not info.st_mode&0o022,'protected_existing_operations_required')
 for name,pin in DEPENDENCIES.items():
  p=OPS/name;i=p.lstat();require(stat.S_ISREG(i.st_mode)and i.st_uid==0 and not i.st_mode&0o022 and i.st_nlink==1 and sha(p.read_bytes())==pin,'exact_retained_public_dependency_required')
